(() => { 'use strict'; const VERSION = '0.1.0'; const VALIDATED_FORM_SELECTOR = 'form[ms-code-submit-form]'; const BOUND_ATTRIBUTE = 'data-tdb-forms-bound'; const PLACEHOLDER_SELECT_SELECTOR = [ '#Treatment-Of-Interest', 'select[name="Treatment-Of-Interest"]', 'select[name="Treatment Of Interest"]' ].join(','); const PHONE_SELECTOR = 'input[name="phone" i], input[name^="phone" i]'; function groupHasCheckedField(form, field) { if (!field.name) return field.checked; return Array.from(form.elements).some(candidate => candidate !== field && candidate.type === field.type && candidate.name === field.name && candidate.checked ) || field.checked; } function requiredFieldsAreComplete(form) { const requiredFields = Array.from( form.querySelectorAll('input[required], select[required], textarea[required]') ).filter(field => !field.disabled); const checkedGroups = new Set(); for (const field of requiredFields) { if (field.type === 'checkbox' || field.type === 'radio') { const groupKey = `${field.type}:${field.name || field.id || 'unnamed'}`; if (checkedGroups.has(groupKey)) continue; checkedGroups.add(groupKey); if (!groupHasCheckedField(form, field)) return false; continue; } if (String(field.value ?? '').trim() === '') return false; } return true; } function updateSubmitState(form) { if (!form.matches(VALIDATED_FORM_SELECTOR)) return; const submitButton = form.querySelector( 'input[type="submit"], button[type="submit"]' ); if (!submitButton) return; const enabled = requiredFieldsAreComplete(form); submitButton.classList.toggle('submit-enabled', enabled); submitButton.disabled = !enabled; } function updateSelectPlaceholder(select) { select.classList.toggle('placeholder', select.value === ''); } function bindPlaceholderSelects(form) { form.querySelectorAll(PLACEHOLDER_SELECT_SELECTOR).forEach(select => { updateSelectPlaceholder(select); if (select.dataset.tdbPlaceholderBound === 'true') return; select.dataset.tdbPlaceholderBound = 'true'; select.addEventListener('change', () => updateSelectPlaceholder(select)); }); } function normaliseUkMobile(value) { const digits = String(value || '').replace(/[^\d]/g, ''); if (/^00447\d{9}$/.test(digits)) return `+44${digits.slice(4)}`; if (/^4407\d{9}$/.test(digits)) return `+44${digits.slice(3)}`; if (/^07\d{9}$/.test(digits)) return `+44${digits.slice(1)}`; if (/^7\d{9}$/.test(digits)) return `+44${digits}`; if (/^447\d{9}$/.test(digits)) return `+${digits}`; return value; } function normalisePhoneFields(form) { form.querySelectorAll(PHONE_SELECTOR).forEach(phoneInput => { phoneInput.value = normaliseUkMobile(phoneInput.value); }); } function bindForm(form) { if (!(form instanceof HTMLFormElement)) return; bindPlaceholderSelects(form); updateSubmitState(form); if (form.getAttribute(BOUND_ATTRIBUTE) === 'true') return; form.setAttribute(BOUND_ATTRIBUTE, 'true'); if (form.matches(VALIDATED_FORM_SELECTOR)) { form.addEventListener('input', () => updateSubmitState(form)); form.addEventListener('change', event => { if (event.target?.matches?.(PLACEHOLDER_SELECT_SELECTOR)) { updateSelectPlaceholder(event.target); } updateSubmitState(form); }); } form.addEventListener( 'submit', () => { normalisePhoneFields(form); updateSubmitState(form); }, true ); } function refresh(root = document) { if (root instanceof Element) { const parentForm = root.closest('form'); if (parentForm) bindForm(parentForm); } if (root instanceof HTMLFormElement) bindForm(root); root.querySelectorAll?.('form').forEach(bindForm); } function start() { refresh(); const observer = new MutationObserver(mutations => { mutations.forEach(mutation => { mutation.addedNodes.forEach(node => { if (node instanceof Element) refresh(node); }); }); }); observer.observe(document.body, { childList: true, subtree: true }); window.TDBForms = Object.freeze({ version: VERSION, refresh: () => refresh() }); } if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', start, { once: true }); } else { start(); } })();